+import React, { useEffect, useState } from 'react';
+import type { Contract, NodeData, EdgeData, Group, FlowPath, FlowStep, RunRecord } from '../types';
+import { Plus, Trash2, FolderPlus, List, Info, ChevronRight, Activity, Settings } from 'lucide-react';
+
+interface SidebarProps {
+  contract: Contract;
+  selectedNode: NodeData | null;
+  selectedEdge: EdgeData | null;
+  activeFlowId: number | null;
+  onUpdateContract: (updater: (prev: Contract) => Contract) => void;
+  onSelectNode: (node: NodeData | null) => void;
+  onSelectEdge: (edge: EdgeData | null) => void;
+  onTriggerAutoLayout: () => void;
+  onSelectFlow: (flowId: number | null) => void;
+  onOpenImportExport: (mode: 'import' | 'export') => void;
+  // Drawings support
+  drawingsIndex: any[];
+  currentDrawingId: string;
+  onLoadDrawing: (id: string) => void;
+  onNewDrawing: () => void;
+  storageMode: 'backend' | 'local';
+  runs: RunRecord[];
+}
+
+export const Sidebar: React.FC<SidebarProps> = ({
+  contract,
+  selectedNode,
+  selectedEdge,
+  activeFlowId,
+  onUpdateContract,
+  onSelectNode,
+  onSelectEdge,
+  onTriggerAutoLayout,
+  onSelectFlow,
+  onOpenImportExport,
+  drawingsIndex,
+  currentDrawingId,
+  onLoadDrawing,
+  onNewDrawing,
+  storageMode,
+  runs
+}) => {
+  const formatRunDate = (timestamp: string) => {
+    const date = new Date(timestamp);
+    if (Number.isNaN(date.getTime())) return timestamp;
+    return new Intl.DateTimeFormat('pt-BR', {
+      day: '2-digit',
+      month: '2-digit',
+      year: 'numeric',
+      hour: '2-digit',
+      minute: '2-digit',
+      timeZoneName: 'short',
+      timeZone: 'America/Sao_Paulo'
+    }).format(date);
+  };
